import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';

import 'employee_screen.dart';
import 'firebase_options.dart';

Future<void> main() async {
  // Required before calling native code (Firebase) ahead of runApp().
  WidgetsFlutterBinding.ensureInitialized();

  // Options generated by `flutterfire configure` (lib/firebase_options.dart)
  // for Android and Web. Android also uses android/app/google-services.json.
  Object? initError;
  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
  } catch (e) {
    initError = e;
  }

  runApp(EmployeeApp(initError: initError));
}

class EmployeeApp extends StatelessWidget {
  const EmployeeApp({super.key, this.initError});

  /// Non-null when Firebase failed to initialize.
  final Object? initError;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Employee Application',
      debugShowCheckedModeBanner: true,
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.deepPurple),
        useMaterial3: true,
      ),
      home: initError == null
          ? const EmployeeScreen()
          : _FirebaseErrorScreen(error: initError!),
    );
  }
}

/// Shown instead of the employee screen when Firebase could not start,
/// so the problem is visible rather than a blank or crashing app.
class _FirebaseErrorScreen extends StatelessWidget {
  const _FirebaseErrorScreen({required this.error});

  final Object error;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        backgroundColor: Colors.yellow,
        title: const Text('Employee Application'),
      ),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Text(
            'Firebase initialization failed.\n\n'
            'Check lib/firebase_options.dart (run `flutterfire configure`) '
            'and android/app/google-services.json.\n\nError: $error',
            textAlign: TextAlign.center,
            style: const TextStyle(color: Colors.red),
          ),
        ),
      ),
    );
  }
}
